// SPDX-License-Identifier: GPL-3.0-or-later
//! `cargo xtask gen [--check]`: dumps the command registry's catalogs (arch §5.3, WP-1N.01).
//!
//! Generated files (all relative to the workspace root, LF endings, 2-space JSON, sorted keys):
//!
//! | File | Content |
//! |---|---|
//! | `schema/commands.json`, `schema/queries.json` | full catalog: flags, MCP exposure, annotations, input/output JSON Schema, error codes |
//! | `schema/events.json` | events the engine broadcasts |
//! | `schema/mcp-tools.json` | core MCP tools (`item.move` is `item_move`) |
//! | `schema/patch-fixtures.json` | RFC 6902-style patches produced by real commands, for the TS patch applier |
//! | `schema/schema-hash.txt`, `crates/cutweave-commands/src/schema_hash.rs` | sha256 of `commands.json` |
//! | `docs/reference/commands.md` | human-readable command table |
//!
//! `--check` regenerates in memory and compares against the files on disk, printing a unified
//! diff and failing when any differ. Nothing here reads the clock or a random source: patch
//! fixtures run against a document with seeded IDs.

use std::collections::BTreeMap;
use std::fmt::Write as _;
use std::fs;
use std::path::Path;

use cutweave_commands::{
    Access, CmdError, EntryKind, McpExposure, Registry, Transaction, apply_patch_json,
    commands_catalog, mcp_tools_catalog, queries_catalog,
};
use cutweave_model::{Project, SeededGen};
use cutweave_ops::media::FakeProbe;
use serde_json::{Value, json};
use sha2::{Digest, Sha256};

/// Generated files by workspace-relative, `/`-separated path.
pub type Files = BTreeMap<String, Vec<u8>>;

const COMMANDS: &str = "schema/commands.json";
const QUERIES: &str = "schema/queries.json";
const EVENTS: &str = "schema/events.json";
const MCP_TOOLS: &str = "schema/mcp-tools.json";
const FIXTURES: &str = "schema/patch-fixtures.json";
const HASH_TXT: &str = "schema/schema-hash.txt";
const HASH_RS: &str = "crates/cutweave-commands/src/schema_hash.rs";
const REFERENCE: &str = "docs/reference/commands.md";

/// The registry as the engine builds it: every `cutweave-ops` namespace plus the `edit.*`
/// history commands of `cutweave-commands`.
///
/// # Errors
/// A registration that breaks the contract (a bug).
pub fn build_registry() -> Result<Registry, String> {
    let mut registry = Registry::new();
    cutweave_ops::register(&mut registry).map_err(|e| e.to_string())?;
    cutweave_commands::edit::register(&mut registry).map_err(|e| e.to_string())?;
    Ok(registry)
}

/// Recursively sorts object keys, so output never depends on declaration order.
fn sorted(value: Value) -> Value {
    match value {
        Value::Object(map) => {
            let mut entries: Vec<_> = map.into_iter().collect();
            entries.sort_by(|a, b| a.0.cmp(&b.0));
            Value::Object(entries.into_iter().map(|(k, v)| (k, sorted(v))).collect())
        }
        Value::Array(items) => Value::Array(items.into_iter().map(sorted).collect()),
        other => other,
    }
}

/// Stable pretty JSON: sorted keys, 2 spaces, LF, trailing newline.
fn json_bytes(value: Value) -> Result<Vec<u8>, String> {
    let mut text = serde_json::to_string_pretty(&sorted(value)).map_err(|e| e.to_string())?;
    text.push('\n');
    Ok(text.into_bytes())
}

fn sha256_hex(bytes: &[u8]) -> String {
    Sha256::digest(bytes)
        .iter()
        .fold(String::with_capacity(64), |mut s, b| {
            let _ = write!(s, "{b:02x}");
            s
        })
}

fn flags(meta: &cutweave_commands::CommandMeta) -> String {
    let mut out = vec![match meta.kind {
        EntryKind::Command => "command",
        EntryKind::Query => "query",
        EntryKind::Engine => "engine",
    }];
    if meta.undoable {
        out.push("undoable");
    }
    if meta.view {
        out.push("view");
    }
    if meta.annotations.read_only && meta.kind != EntryKind::Query {
        out.push("read-only");
    }
    if meta.annotations.destructive {
        out.push("destructive");
    }
    if meta.annotations.idempotent && meta.kind != EntryKind::Query {
        out.push("idempotent");
    }
    if meta.annotations.open_world {
        out.push("open-world");
    }
    if meta.scope == cutweave_commands::Scope::UiOnly {
        out.push("ui-only");
    }
    if !meta.secret_fields.is_empty() {
        out.push("secret-params");
    }
    out.join(", ")
}

fn cell(text: &str) -> String {
    text.replace('|', "\\|")
}

fn reference_markdown(registry: &Registry) -> String {
    let mut out = String::new();
    out.push_str("<!-- @generated by cargo xtask gen; do not edit -->\n\n");
    out.push_str("# Command reference\n\n");
    let _ = writeln!(
        out,
        "Every command and query the engine registers ({} in total), generated from the \
         registry. The full JSON Schemas are in `schema/commands.json` and `schema/queries.json`.\n",
        registry.len()
    );
    out.push_str(
        "MCP exposure: `core` commands are always listed as tools (`item.move` is `item_move`), \
         `catalog` ones are reachable through the catalog tools, `hidden` ones are not exposed.\n\n",
    );
    out.push_str("| Namespace | Command | Summary | Flags | MCP |\n|---|---|---|---|---|\n");
    for entry in registry.list() {
        let meta = &entry.meta;
        let mcp = match meta.mcp {
            McpExposure::Core => "core",
            McpExposure::Catalog => "catalog",
            McpExposure::Hidden => "hidden",
        };
        let _ = writeln!(
            out,
            "| {} | `{}` | {} | {} | {} |",
            meta.namespace(),
            meta.name,
            cell(meta.summary),
            flags(meta),
            mcp
        );
    }
    out
}

/// One fixture step: runs `name` in a transaction on `doc`, commits and records the patches.
fn step(
    registry: &Registry,
    ids: &mut SeededGen,
    doc: &mut Project,
    label: &str,
    name: &str,
    input: &Value,
) -> Result<(Value, Value), String> {
    let before = doc.clone();
    let mut txn = Transaction::begin(before.clone());
    let output = {
        let mut tx = txn.tx(ids, Access::STANDARD);
        registry
            .invoke_json(name, input.clone(), &mut tx)
            .map_err(|e: CmdError| format!("fixture `{label}` ({name}) failed: {e}"))?
    };
    let committed = txn.commit();
    let before_json = serde_json::to_value(&before).map_err(|e| e.to_string())?;
    let after_json = serde_json::to_value(&committed.doc).map_err(|e| e.to_string())?;
    // The fixture contract: both patches work on the JSON mirror of the document.
    for (which, patch, from, to) in [
        ("forward", &committed.patch, &before_json, &after_json),
        ("inverse", &committed.inverse, &after_json, &before_json),
    ] {
        let mut applied = from.clone();
        apply_patch_json(&mut applied, patch)
            .map_err(|e| format!("fixture `{label}`: {which} patch does not apply: {e}"))?;
        if &applied != to {
            return Err(format!(
                "fixture `{label}`: {which} patch does not reproduce the document"
            ));
        }
    }
    let fixture = json!({
        "name": label,
        "command": name,
        "input": input,
        "output": output,
        "before": before_json,
        "after": after_json,
        "forward_patch": committed.patch,
        "inverse_patch": committed.inverse,
    });
    *doc = committed.doc;
    Ok((fixture, output))
}

fn patch_fixtures(registry: &Registry) -> Result<Value, String> {
    // Seeded IDs (`--deterministic-ids` machinery, ADR-0015): the same seed gives the same IDs
    // on every platform.
    let mut ids = SeededGen::new(1);
    let mut doc = Project::new("Untitled");
    let mut fixtures = Vec::new();
    let mut run = |label: &str, name: &str, input: Value| -> Result<Value, String> {
        let (fixture, output) = step(registry, &mut ids, &mut doc, label, name, &input)?;
        fixtures.push(fixture);
        Ok(output)
    };

    let created = run("project.new", "project.new", json!({"name": "Demo"}))?;
    let sequence = created["sequence"].clone();
    let video = created["video_track"].clone();
    let probed = FakeProbe::video("/media/interview.mp4", 10, true);
    let registered = run(
        "media.register",
        "media.register",
        json!({
            "path": "/media/interview.mp4",
            "probe": probed.probe,
            "content_hash": probed.content_hash,
        }),
    )?;
    let added = run(
        "track.add",
        "track.add",
        json!({"sequence": sequence, "kind": "video", "name": "B-roll"}),
    )?;
    // 2 s = 1_411_200_000 flicks: times are plain JSON integers on the wire (ADR-0015).
    let inserted = run(
        "timeline.insert",
        "timeline.insert",
        json!({
            "sequence": sequence,
            "track": video,
            "media": registered["media_id"],
            "at": 1_411_200_000_i64,
        }),
    )?;
    let clip = inserted["clips"][0].clone();
    // Split 4 s into the clip (6 s = 4_233_600_000 flicks); linked audio splits too.
    run(
        "clip.split",
        "clip.split",
        json!({"item": clip, "at": 4_233_600_000_i64}),
    )?;
    // Move the left half (and its linked partner) to 30 s.
    run(
        "item.move",
        "item.move",
        json!({"item": clip, "start": 21_168_000_000_i64}),
    )?;
    run(
        "track.set",
        "track.set",
        json!({"track": added["track"], "muted": true}),
    )?;
    run(
        "project.rename",
        "project.rename",
        json!({"name": "Demo cut"}),
    )?;
    run(
        "track.remove",
        "track.remove",
        json!({"track": added["track"]}),
    )?;

    // `edit.undo` of the last step is its inverse patch: derived from the last fixture.
    let last = fixtures
        .last()
        .cloned()
        .ok_or("no fixtures were produced")?;
    fixtures.push(json!({
        "name": "edit.undo of track.remove",
        "command": "edit.undo",
        "input": {},
        "output": null,
        "before": last["after"],
        "after": last["before"],
        "forward_patch": last["inverse_patch"],
        "inverse_patch": last["forward_patch"],
    }));

    Ok(json!({
        "format": cutweave_commands::CATALOG_FORMAT,
        "description": "Patches produced by real commands on a document with seeded IDs. Each \
            fixture applies `forward_patch` to `before` to get `after`, and `inverse_patch` to \
            `after` to get `before`. Patches are RFC 6902-style arrays of ops addressed by JSON \
            Pointer (ID-keyed, with preimages).",
        "id_seed": 1,
        "fixtures": fixtures,
    }))
}

/// Payload type of each engine event (their wire types are serde-only, so no JSON Schema yet).
fn engine_event_payload(name: &str) -> &'static str {
    match name {
        "project.dirty" => "ProjectDirty",
        "project.saved" => "ProjectSaved",
        "project.recovery_available" => "RecoveryPayload",
        "project.autosave_failed" => "AutosaveFailed",
        _ => "unknown",
    }
}

/// `schema/events.json`: document events (`cutweave-commands`, source `doc`) joined with engine
/// events (`cutweave-engine`, source `engine`), sorted by name. `cutweave-commands` cannot
/// depend on the engine, so the join happens here. New event sources append here.
fn events_catalog() -> Value {
    let mut events: Vec<Value> = cutweave_commands::EVENT_CATALOG
        .iter()
        .map(|e| {
            json!({"name": e.name, "summary": e.summary, "payload": e.payload, "source": "doc"})
        })
        .collect();
    events.extend(
        cutweave_engine::autosave::PROJECT_EVENTS
            .iter()
            .map(|(name, summary)| {
                json!({
                    "name": name,
                    "summary": summary,
                    "payload": engine_event_payload(name),
                    "source": "engine",
                })
            }),
    );
    events.sort_by(|a, b| a["name"].as_str().cmp(&b["name"].as_str()));
    json!({"format": cutweave_commands::CATALOG_FORMAT, "events": events})
}

/// Builds every generated file in memory.
///
/// # Errors
/// A broken registry, or a fixture that does not reproduce.
pub fn generate() -> Result<Files, String> {
    let registry = build_registry()?;
    let mut files = Files::new();
    let commands = json_bytes(commands_catalog(&registry))?;
    let hash = sha256_hex(&commands);
    files.insert(COMMANDS.into(), commands);
    files.insert(QUERIES.into(), json_bytes(queries_catalog(&registry))?);
    files.insert(EVENTS.into(), json_bytes(events_catalog())?);
    files.insert(MCP_TOOLS.into(), json_bytes(mcp_tools_catalog(&registry))?);
    files.insert(FIXTURES.into(), json_bytes(patch_fixtures(&registry)?)?);
    files.insert(HASH_TXT.into(), format!("{hash}\n").into_bytes());
    files.insert(
        HASH_RS.into(),
        format!(
            "// SPDX-License-Identifier: GPL-3.0-or-later\n\
             // @generated by `cargo xtask gen`; do not edit.\n\
             //! Hash of the committed command catalog (`schema/commands.json`).\n\n\
             /// Lowercase hex sha256 of the bytes of `schema/commands.json`. The engine reports it in\n\
             /// `rpc.hello`; clients compare it with the one generated into `@cutweave/protocol`.\n\
             pub const SCHEMA_HASH: &str = \"{hash}\";\n"
        )
        .into_bytes(),
    );
    files.insert(REFERENCE.into(), reference_markdown(&registry).into_bytes());
    Ok(files)
}

/// Writes `files` under `root`.
///
/// # Errors
/// I/O failures.
pub fn write(root: &Path, files: &Files) -> Result<(), String> {
    for (rel, bytes) in files {
        let path = root.join(rel);
        if let Some(dir) = path.parent() {
            fs::create_dir_all(dir).map_err(|e| format!("{}: {e}", dir.display()))?;
        }
        // Skip identical files so mtimes stay put (and rebuilds are not triggered).
        if fs::read(&path).is_ok_and(|old| &old == bytes) {
            continue;
        }
        fs::write(&path, bytes).map_err(|e| format!("{}: {e}", path.display()))?;
    }
    Ok(())
}

/// Compares `files` with the committed files under `root`.
///
/// # Errors
/// The unified diff of everything that differs (a missing file diffs against empty).
pub fn check(root: &Path, files: &Files) -> Result<(), String> {
    let mut report = String::new();
    for (rel, expected) in files {
        let committed = fs::read(root.join(rel)).unwrap_or_default();
        if &committed == expected {
            continue;
        }
        let old = String::from_utf8_lossy(&committed);
        let new = String::from_utf8_lossy(expected);
        let diff = similar::TextDiff::from_lines(old.as_ref(), new.as_ref());
        let _ = write!(
            report,
            "{}",
            diff.unified_diff().context_radius(3).header(
                &format!("a/{rel} (committed)"),
                &format!("b/{rel} (generated)")
            )
        );
        if committed.is_empty() {
            let _ = writeln!(report, "(`{rel}` is missing or empty)");
        }
    }
    if report.is_empty() {
        Ok(())
    } else {
        Err(report)
    }
}

/// `cargo xtask gen [--check]`.
pub fn run(root: &Path, args: &[String]) -> bool {
    let check_only = match args {
        [] => false,
        [flag] if flag == "--check" => true,
        _ => {
            eprintln!("gen: usage: cargo xtask gen [--check]");
            return false;
        }
    };
    let files = match generate() {
        Ok(f) => f,
        Err(e) => {
            eprintln!("gen: {e}");
            return false;
        }
    };
    if check_only {
        match check(root, &files) {
            Ok(()) => {
                println!("gen --check: ok ({} files up to date)", files.len());
                true
            }
            Err(diff) => {
                eprintln!("{diff}");
                eprintln!(
                    "gen --check: generated files are out of date; run `cargo xtask gen`, review \
                     the diff and commit it"
                );
                false
            }
        }
    } else {
        match write(root, &files) {
            Ok(()) => {
                println!("gen: wrote {} files", files.len());
                true
            }
            Err(e) => {
                eprintln!("gen: {e}");
                false
            }
        }
    }
}

#[cfg(test)]
mod tests {
    #![allow(clippy::unwrap_used, clippy::expect_used)]
    use super::*;
    use std::path::PathBuf;

    struct TempDir(PathBuf);

    impl TempDir {
        fn new(name: &str) -> TempDir {
            let dir =
                std::env::temp_dir().join(format!("cutweave-gen-{name}-{}", std::process::id()));
            let _ = fs::remove_dir_all(&dir);
            fs::create_dir_all(&dir).unwrap();
            TempDir(dir)
        }
    }

    impl Drop for TempDir {
        fn drop(&mut self) {
            let _ = fs::remove_dir_all(&self.0);
        }
    }

    /// The review gate (arch §5.3): any change to the command catalog changes this snapshot, so
    /// it needs `cargo insta review` in addition to regenerating `schema/`.
    #[test]
    fn commands_catalog_snapshot() {
        let files = generate().unwrap();
        let text = String::from_utf8(files[COMMANDS].clone()).unwrap();
        insta::assert_snapshot!("commands_json", text);
    }

    #[test]
    fn generation_is_deterministic() {
        assert_eq!(generate().unwrap(), generate().unwrap());
    }

    #[test]
    fn running_gen_twice_writes_identical_files() {
        let dir = TempDir::new("twice");
        let files = generate().unwrap();
        write(&dir.0, &files).unwrap();
        let first: Vec<_> = files
            .keys()
            .map(|rel| fs::read(dir.0.join(rel)).unwrap())
            .collect();
        write(&dir.0, &generate().unwrap()).unwrap();
        let second: Vec<_> = files
            .keys()
            .map(|rel| fs::read(dir.0.join(rel)).unwrap())
            .collect();
        assert_eq!(first, second);
        assert_eq!(check(&dir.0, &files), Ok(()));
    }

    #[test]
    fn every_registered_entry_appears_exactly_once() {
        let registry = build_registry().unwrap();
        let files = generate().unwrap();
        let count = |rel: &str, key: &str| -> usize {
            let v: Value = serde_json::from_slice(&files[rel]).unwrap();
            v[key].as_array().unwrap().len()
        };
        let queries = registry
            .list()
            .filter(|e| e.kind() == EntryKind::Query)
            .count();
        assert_eq!(count(QUERIES, "queries"), queries);
        assert_eq!(count(COMMANDS, "commands"), registry.len() - queries);
        assert_eq!(
            count(COMMANDS, "commands") + count(QUERIES, "queries"),
            registry.len()
        );
        // Every name is present in the human reference too.
        let md = String::from_utf8(files[REFERENCE].clone()).unwrap();
        for entry in registry.list() {
            assert!(
                md.contains(&format!("`{}`", entry.name())),
                "{}",
                entry.name()
            );
        }
    }

    #[test]
    fn output_is_lf_only_sorted_and_free_of_absolute_paths() {
        for (rel, bytes) in generate().unwrap() {
            let text = String::from_utf8(bytes).unwrap();
            assert!(!text.contains('\r'), "{rel} has CR");
            assert!(text.ends_with('\n'), "{rel} lacks a trailing newline");
            assert!(!text.contains("D:\\") && !text.contains("C:\\"), "{rel}");
            assert!(
                !text.contains("/home/") && !text.contains("/Users/"),
                "{rel}"
            );
            if std::path::Path::new(&rel)
                .extension()
                .is_some_and(|e| e == "json")
            {
                let value: Value = serde_json::from_str(&text).unwrap();
                assert_eq!(
                    serde_json::to_string_pretty(&sorted(value)).unwrap() + "\n",
                    text,
                    "{rel} is not in canonical form"
                );
            }
        }
    }

    #[test]
    fn schema_hash_is_the_sha256_of_commands_json() {
        let files = generate().unwrap();
        let hash = sha256_hex(&files[COMMANDS]);
        assert_eq!(hash.len(), 64);
        assert_eq!(
            String::from_utf8(files[HASH_TXT].clone()).unwrap(),
            format!("{hash}\n")
        );
        assert!(
            String::from_utf8(files[HASH_RS].clone())
                .unwrap()
                .contains(&format!("\"{hash}\""))
        );
    }

    #[test]
    fn mcp_tool_names_follow_the_snake_case_rule() {
        let files = generate().unwrap();
        let v: Value = serde_json::from_slice(&files[MCP_TOOLS]).unwrap();
        for tool in v["tools"].as_array().unwrap() {
            let command = tool["command"].as_str().unwrap();
            assert_eq!(tool["name"], command.replace('.', "_"));
        }
    }

    #[test]
    fn events_join_doc_and_engine_sources_sorted() {
        let files = generate().unwrap();
        let v: Value = serde_json::from_slice(&files[EVENTS]).unwrap();
        let events = v["events"].as_array().unwrap();
        let names: Vec<_> = events.iter().map(|e| e["name"].as_str().unwrap()).collect();
        let mut sorted = names.clone();
        sorted.sort_unstable();
        assert_eq!(names, sorted);
        let source = |n: &str| events.iter().find(|e| e["name"] == n).unwrap()["source"].clone();
        assert_eq!(source("doc.patched"), "doc");
        assert_eq!(source("tx.opened"), "doc");
        for (n, _) in cutweave_engine::autosave::PROJECT_EVENTS {
            assert_eq!(source(n), "engine", "{n}");
            assert_ne!(engine_event_payload(n), "unknown", "{n}");
        }
        assert_eq!(
            events.len(),
            cutweave_commands::EVENT_CATALOG.len()
                + cutweave_engine::autosave::PROJECT_EVENTS.len()
        );
    }

    #[test]
    fn fixtures_cover_the_core_commands() {
        let files = generate().unwrap();
        let v: Value = serde_json::from_slice(&files[FIXTURES]).unwrap();
        let names: Vec<_> = v["fixtures"]
            .as_array()
            .unwrap()
            .iter()
            .map(|f| f["command"].as_str().unwrap())
            .collect();
        for expected in [
            "project.new",
            "track.add",
            "timeline.insert",
            "clip.split",
            "item.move",
            "edit.undo",
        ] {
            assert!(names.contains(&expected), "{expected} in {names:?}");
        }
    }

    #[test]
    fn stale_committed_file_fails_the_check_with_a_diff() {
        let dir = TempDir::new("stale");
        let files = generate().unwrap();
        write(&dir.0, &files).unwrap();
        assert_eq!(check(&dir.0, &files), Ok(()));

        // A schema-affecting change that was not regenerated: the committed copy lacks a field.
        let path = dir.0.join(COMMANDS);
        let committed = fs::read_to_string(&path).unwrap();
        let mutated = committed.replacen("\"summary\"", "\"summary_old\"", 1);
        assert_ne!(mutated, committed);
        fs::write(&path, mutated).unwrap();

        let diff = check(&dir.0, &files).unwrap_err();
        assert!(diff.contains("--- a/schema/commands.json"), "{diff}");
        assert!(diff.contains("+++ b/schema/commands.json"), "{diff}");
        assert!(diff.contains("-      \"summary_old\""), "{diff}");
        assert!(diff.contains("+      \"summary\""), "{diff}");
        // Only the stale file is reported.
        assert!(!diff.contains("schema/queries.json"), "{diff}");
    }

    #[test]
    fn missing_committed_file_fails_the_check() {
        let dir = TempDir::new("missing");
        let files = generate().unwrap();
        let err = check(&dir.0, &files).unwrap_err();
        assert!(err.contains("is missing or empty"), "{err}");
    }
}
